package io.github.diodeme.ji.artifact;

import java.util.Arrays;

/** Authorized range response with strong SHA-256 ETag. */
public record ArtifactRead(byte[] bytes, String mediaType, String etag, String contentRange, long totalBytes) {
    public ArtifactRead { bytes = Arrays.copyOf(bytes, bytes.length); }
    @Override public byte[] bytes() { return Arrays.copyOf(bytes, bytes.length); }
}
